with with_windows as (select id, order_id, product_id, quantity, unit_price, row_number() over w_recent as row_seq, ntile(3) over (partition by product_id order by unit_price asc, id asc) as unit_price_bucket, ntile(5) over (partition by order_id order by quantity desc, id asc) as quantity_bucket from order_items window w_recent as (order by quantity desc, id asc)) select order_id, avg(quantity) as avg_quantity, stddev_samp(unit_price) as unit_price_stddev, round(avg(quantity_bucket), 2) as avg_quantity_bucket, approx_percentile(unit_price, 0.95) as unit_price_p95 from with_windows group by 1 order by order_id desc nulls last;
